#define DT_DRV_COMPAT zephyr_eeprom_sim

#include <zephyr/device.h>
#include <zephyr/drivers/eeprom.h>
#include <zephyr/kernel.h>

struct eeprom_sim_config {
	size_t size;
};

struct eeprom_sim_data {
	uint8_t *buf;
};

static int eeprom_sim_read(const struct device *dev, off_t offset, void *buf,
			 size_t len)
{
	const struct eeprom_sim_config *config = dev->config;
	struct eeprom_sim_data *data = dev->data;

	if (len == 0) {
		return 0;
	}

	if (offset < 0 || offset > config->size || len > config->size - offset) {
		return -EINVAL;
	}

	memcpy(buf, data->buf + offset, len);

	return 0;
}

static int eeprom_sim_write(const struct device *dev, off_t offset,
			  const void *buf, size_t len)
{
	const struct eeprom_sim_config *config = dev->config;
	struct eeprom_sim_data *data = dev->data;

	if (len == 0) {
		return 0;
	}

	if (offset < 0 || offset > config->size || len > config->size - offset) {
		return -EINVAL;
	}

	memcpy(data->buf + offset, buf, len);

	return 0;
}

static size_t eeprom_sim_size(const struct device *dev)
{
	const struct eeprom_sim_config *config = dev->config;

	return config->size;
}

static int eeprom_sim_init(const struct device *dev)
{
	const struct eeprom_sim_config *config = dev->config;
	struct eeprom_sim_data *data = dev->data;

	data->buf = k_malloc(config->size);
	if (data->buf == NULL) {
		return -ENOMEM;
	}
	memset(data->buf, 0, config->size);

	return 0;
}

static const struct eeprom_driver_api eeprom_sim_api = {
	.read = eeprom_sim_read,
	.write = eeprom_sim_write,
	.size = eeprom_sim_size,
};

#define EEPROM_SIM_INIT(n)						\
	static struct eeprom_sim_data eeprom_sim_data_##n;		\
									\
	static const struct eeprom_sim_config eeprom_sim_config_##n = {	\
		.size = DT_INST_PROP(n, size),				\
	};								\
									\
	DEVICE_DT_INST_DEFINE(n, eeprom_sim_init, NULL,			\
			      &eeprom_sim_data_##n,			\
			      &eeprom_sim_config_##n, POST_KERNEL,	\
			      CONFIG_EEPROM_INIT_PRIORITY,		\
			      &eeprom_sim_api);

DT_INST_FOREACH_STATUS_OKAY(EEPROM_SIM_INIT)
